import json, re
from datetime import datetime
from collections import defaultdict

rows = [json.loads(line) for line in open('commits.jsonl', encoding='utf-8') if line.strip()]

mailmap = {}
for line in open('.mailmap', encoding='utf-8'):
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    m = re.match(r'^(.+?) <([^>]+)>(?: <([^>]+)>)?$', line)
    if m:
        name, proper_email, old_email = m.groups()
        mailmap[proper_email] = name
        if old_email:
            mailmap[old_email] = name

def canonical_name(name, email):
    return mailmap.get(email, name)

header_re = re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (?! )(.*)$')
revert_target_re = re.compile(r'^This reverts commit ([0-9a-fA-F]{7,40})\.$')
fix_re = re.compile(r'^Fixes #(\d+)$')
coauthor_re = re.compile(r'^Co-authored-by: (.+) <([^>]+)>$')

reverted = set()
for row in rows:
    for line in row['message'].split('\n'):
        m = revert_target_re.match(line)
        if m:
            reverted.add(m.group(1).lower())

commits = []
for row in rows:
    header = row['message'].split('\n')[0]
    if header.startswith('Revert "'):
        continue
    commit_hash = row['hash'].lower()
    if commit_hash in reverted or any(commit_hash.startswith(target) for target in reverted):
        continue

    match = header_re.match(header)
    if not match:
        continue
    kind, scope, bang, summary = match.groups()
    bang = bool(bang)
    if not (bang or kind in ('feat', 'fix', 'perf')):
        continue

    scope = scope or 'general'
    if scope == 'internal' and not bang:
        continue
    if scope == 'deps':
        scope = 'dependencies'

    normalized = summary[0].upper() + summary[1:]
    if normalized.endswith('.'):
        normalized = normalized[:-1]
    if kind == 'perf':
        normalized += ' [perf]'

    section = 'Breaking changes' if bang else ('Features' if kind in ('feat', 'perf') else 'Fixes')

    refs = []
    if kind == 'fix':
        for line in row['message'].split('\n')[1:]:
            fix_match = fix_re.match(line)
            if fix_match:
                refs.append(fix_match.group(1))

    commits.append({
        'hash': row['hash'],
        'date': datetime.fromisoformat(row['date']),
        'scope': scope,
        'summary': normalized,
        'section': section,
        'refs': refs,
        'author': row['author'],
        'email': row['email'],
        'message': row['message'],
    })

groups = defaultdict(list)
for commit in commits:
    groups[(commit['section'], commit['scope'], commit['summary'])].append(commit)

sections = defaultdict(list)
for (section, scope, summary), group in groups.items():
    group.sort(key=lambda commit: commit['date'], reverse=True)
    refs = []
    for commit in group:
        for number in commit['refs']:
            if number not in refs:
                refs.append(number)
    hashes = [commit['hash'][:7] for commit in group]

    prefix = f'- **{scope}:** '
    refs_text = ''.join(f' (#{number})' for number in refs)
    hashes_text = f" ({', '.join(hashes)})"
    entry = prefix + summary + refs_text + hashes_text
    if len(entry) > 100:
        available = 100 - len(prefix) - len(refs_text) - len(hashes_text)
        summary = summary[:available - 1].rstrip(' ') + '…'
        entry = prefix + summary + refs_text + hashes_text
    assert len(entry) <= 100
    sections[section].append((scope, group[0]['date'], entry))

authored = set()
credits = defaultdict(set)
for commit in commits:
    author_name = canonical_name(commit['author'], commit['email'])
    if not author_name.endswith('[bot]'):
        authored.add(author_name)
        credits[author_name].add(commit['hash'])
    for line in commit['message'].split('\n')[1:]:
        coauthor_match = coauthor_re.match(line)
        if not coauthor_match:
            continue
        name, email = coauthor_match.groups()
        name = canonical_name(name, email)
        if name.endswith('[bot]'):
            continue
        credits[name].add(commit['hash'])

people = sorted(
    ((name, len(hashes)) for name, hashes in credits.items()
     if name in authored and not name.endswith('[bot]')),
    key=lambda item: (-item[1], item[0]),
)

blocks = ['# Release 4.2.0']
for section in ('Breaking changes', 'Features', 'Fixes'):
    if not sections[section]:
        continue
    entries = [item[2] for item in sorted(
        sections[section], key=lambda item: (item[0], -item[1].timestamp())
    )]
    blocks.append(f'## {section}\n\n' + '\n'.join(entries))
if people:
    blocks.append('## Contributors\n\n' + '\n'.join(f'- {name} ({count})' for name, count in people))

text = '\n\n'.join(blocks) + '\n'
assert text.endswith('\n') and not text.endswith('\n\n')
assert not any(line != line.rstrip() for line in text.split('\n'))
assert max(len(line) for line in text.split('\n')[:-1]) <= 100
open('RELEASE_NOTES.md', 'w', encoding='utf-8', newline='\n').write(text)
print('wrote', len(text), 'bytes,', len(text.split('\n')) - 1, 'lines')
