fix_re = re.compile(r'^Fixes #(\d+)$')
co_re = re.compile(r'^Co-authored-by: (.+) <([^>]+)>$')
revert_re = re.compile(r'^This reverts commit ([0-9a-fA-F]{7,40})\.$')

