    if scope == 'deps':
        scope = 'dependencies'
    s = summary[0].upper() + summary[1:]
    if s.endswith('.'):
        s = s[:-1]
    if typ == 'perf':
        s += ' [perf]'
    section = 'Breaking changes' if bang else ('Features' if typ in ('feat', 'perf') else 'Fixes')
    refs = []
    if typ == 'fix':
        for l in r['message'].split('\n')[1:]:
